export async function renderMusic(seconds: number, m: MusicMix, sampleRate = 44100, volume = 0.63): Promise<AudioBuffer> {
  const ctx = new OfflineAudioContext(2, Math.ceil(seconds * sampleRate), sampleRate), rnd = rng(CONFIG.music.seed + 1);
